    let remainingSeconds = null;
    if (isTimer && typeof cv === 'number' && cv > 0) {
        remainingSeconds = (cv - _clockNow[timerBaseById[s.id]]) * 60 - _secs;
        if (remainingSeconds < 0) remainingSeconds = 0;
    }
    return {
        id: s.id,
        name: s.name || s.id,
        type: s.type,
        defaultValue: s.defaultValue,
        currentValue: cv,
        ttl: s.ttl,
