    if (p.keys) PROVIDERS.forEach(k => { if (typeof p.keys[k] === 'string') s.keys[k] = p.keys[k].trim(); });
    if (p.models) PROVIDERS.forEach(k => { if (p.models[k]) s.models[k] = String(p.models[k]).trim(); });
    if (typeof p.reasoning === 'string') s.reasoning = p.reasoning;
    if (p.eraseAllKeys === true) PROVIDERS.forEach(k => s.keys[k] = '');
    if (p.eraseKey && s.keys[p.eraseKey] !== undefined) s.keys[p.eraseKey] = '';
    persist(s);
}

const keySet = {}; PROVIDERS.forEach(k => keySet[k] = !!s.keys[k]);
const active = !!s.keys[s.provider];
node.status({ fill: active ? 'green' : 'grey', shape: 'dot',
    text: (active ? s.provider + '/' + (s.models[s.provider] || '?') : s.provider + ': no key') + (s.reasoning && s.reasoning !== 'off' ? ' [' + s.reasoning + ']' : '') });
msg.statusCode = 200;
msg.payload = { provider: s.provider, keys: s.keys, models: s.models, reasoning: s.reasoning || 'off', keySet: keySet };
return msg;

// Chat Turn Runner: runs the full turn (provider + tool loop) in the background, writing to the
// server-side transcript (flow.chatTranscript) and clearing flow.chatPending when done. Triggered
// by a message (not an HTTP request), so it has NO response timeout — long multi-pass turns are fine.
const settings = global.get('aiChatSettings') || {};
const providers = global.get('aiProviders') || {};
const provider = settings.provider || 'anthropic';
const style = (providers[provider] || {}).style || 'anthropic';
const fetchFn = global.get('fetchFn');
const aiLog = global.get('aiLog') || function () {};
const trim = global.get('aiLogTrim') || function (x) { return x; };
const model = (settings.models && settings.models[provider]) || '?';
const maxTok = (providers[provider] || {}).maxTokens || '?';
const BMS = global.get('BMS');
const text = (msg.payload && msg.payload.text) || '';

function pushT(m) { const t = flow.get('chatTranscript') || []; t.push(m); if (t.length > 300) t.shift(); flow.set('chatTranscript', t); }

if (!fetchFn) { pushT({ role: 'error', text: 'fetchFn not available — check settings.js.' }); flow.set('chatPending', false); return null; }

return (async function () {
    let finalReached = false;
    try {
        let history = flow.get('chatHistory') || [];
        if (flow.get('chatHistoryV') !== 3) { history = []; flow.set('chatHistoryV', 3); }
        history.push({ role: 'user', text: text });
        if (history.length > 40) history = history.slice(-40);

        // Read the provider's own retry hint, if any. Retry-After may be delta-seconds OR an
        // HTTP-date; some APIs use retry-after-ms or x-ratelimit-reset(-tokens). Returns seconds or null.
        const retryHint = function (resp) {
            try {
                const h = resp.headers; if (!h || !h.get) return null;
                const ms = h.get('retry-after-ms') || h.get('x-ratelimit-reset-after-ms');
                if (ms && !isNaN(+ms)) return Math.max(1, Math.ceil(+ms / 1000));
                const ra = h.get('retry-after');
                if (ra) {
                    if (!isNaN(+ra)) return Math.max(1, parseInt(ra, 10));            // delta-seconds
                    const t = Date.parse(ra); if (!isNaN(t)) return Math.max(1, Math.ceil((t - Date.now()) / 1000)); // HTTP-date
                }
                const rs = h.get('x-ratelimit-reset') || h.get('ratelimit-reset');
                if (rs && !isNaN(+rs)) { const n = +rs; return n > 1e6 ? Math.max(1, Math.ceil(n - Date.now() / 1000)) : Math.max(1, Math.ceil(n)); }
            } catch (e) {}
            return null;
        };
        const MAXTRY = 6;
        // Call the provider with backoff on 429 (rate limit) / 5xx. The turn is detached (no client
        // timeout), so we can wait out the rate-limit window and continue rather than failing.
        // chatRetry stays set across the wait (cleared only on a usable response / cancel / give-up)
        // so the UI banner counts down smoothly instead of flickering.
        const callProvider = async function (req) {
            for (let attempt = 0; attempt < MAXTRY; attempt++) {
                if (flow.get('chatCancel')) { flow.set('chatRetry', null); return null; }
                const resp = await fetchFn(req.url, { method: 'POST', headers: req.headers, body: JSON.stringify(req.payload) });
                if (resp.status !== 429 && resp.status < 500) { flow.set('chatRetry', null); return resp; }
                const hint = retryHint(resp);
                let wait, source;
                if (hint != null) { wait = Math.min(300, hint); source = 'api'; }       // trust the provider's hint
                else { wait = Math.min(90, 10 * Math.pow(2, attempt)); source = 'backoff'; }  // 10,20,40,80,90,90 — not optimistic
                aiLog('info', '⏳ HTTP ' + resp.status + ' from ' + provider + ' — ' + (source === 'api' ? 'provider asked to wait ' : 'backing off ') + wait + 's (attempt ' + (attempt + 1) + '/' + MAXTRY + ', source=' + source + ')');
                flow.set('chatRetry', { until: Date.now() + wait * 1000, seconds0: wait, status: resp.status, provider: provider, attempt: attempt + 1, max: MAXTRY, source: source });
                await new Promise(function (r) { setTimeout(r, wait * 1000); });
            }
            flow.set('chatRetry', null);
            return null;   // exhausted retries
        };

        for (let round = 0; round < 10; round++) {
            if (flow.get('chatCancel')) { pushT({ role: 'error', text: '(cancelled)' }); finalReached = true; break; }
            const req = global.get('aiBuildRequest')(history, settings);
            aiLog('request', '→ REQUEST ' + provider + '/' + model + ' (' + history.length + ' msgs)', { url: req.url, body: trim(req.payload) });
            const resp = await callProvider(req);
            if (!resp) { pushT({ role: 'error', text: flow.get('chatCancel') ? '(cancelled)' : ('Rate limit / server errors from ' + provider + ' persisted after retries — try again shortly, switch provider, or upgrade the API tier.') }); finalReached = true; break; }
            let body; try { body = await resp.json(); } catch (e) { body = null; }
            const parsed = global.get('aiParseResponse')(style, resp.status, body);

            if (!parsed.ok) { aiLog('error', '← ERROR ' + resp.status + ': ' + parsed.error, { statusCode: resp.status, body: body }); pushT({ role: 'error', text: parsed.error }); finalReached = true; break; }
            if (parsed.truncated) {
                const wasTool = parsed.toolCalls.length > 0;
                const advice = 'Apply the configuration in smaller parts (merge:true), or raise the provider max_tokens.';
                aiLog('error', '← TRUNCATED ' + provider + ' (max_tokens=' + maxTok + ')' + (wasTool ? ' [tool call discarded]' : ''), { body: body });
                pushT({ role: 'error', text: '⚠ ' + (wasTool ? 'Configuration truncated and NOT applied. ' : 'Reply cut off. ') + advice });
                finalReached = true; break;
            }
            if (parsed.stop === 'tool' && parsed.toolCalls.length) {
                history.push({ role: 'assistant', text: parsed.text, toolCalls: parsed.toolCalls, reasoning: parsed.reasoning });
                if (parsed.text) pushT({ role: 'assistant', text: parsed.text });
                const results = [];
                parsed.toolCalls.forEach(function (tc) {
                    if (tc.name === 'read_config') {
                        const sec = (tc.input && tc.input.section) || '';
                        let slice;
                        if (sec === 'rule_groups') {
                            const gs = global.get('ruleGroups') || [];
                            slice = (tc.input && tc.input.id) ? { rule_group: gs.filter(function (g) { return g.id === tc.input.id; })[0] || null } : { rule_groups: gs };
                        } else if (sec === 'defined_states') slice = { defined_states: global.get('stateRegistry') || [] };
                        else if (sec === 'behavior_agents') slice = { behavior_agents: global.get('behaviorAgents') || [] };
                        else if (sec === 'dashboard') slice = { dashboard: global.get('dashboardConfig') || { widgets: [] } };
                        else slice = { error: 'unknown section: ' + sec };
                        results.push({ id: tc.id, name: tc.name, content: JSON.stringify(slice) });
                        pushT({ role: 'tool', text: '🔎 read ' + sec + (tc.input && tc.input.id ? ' (' + tc.input.id + ')' : ''), ok: true });
                        aiLog('tool', '🔎 read_config ' + sec + (tc.input && tc.input.id ? ' ' + tc.input.id : ''), { input: tc.input });
                        return;
                    }
                    let result = (tc.name === 'apply_bms_config' && BMS && BMS.applyConfig) ? BMS.applyConfig(tc.input) : { errors: ['unknown tool: ' + tc.name] };
                    results.push({ id: tc.id, name: tc.name, content: JSON.stringify(result) });
                    const ok = !(result.errors || []).length, clean = ok && !(result.unknownFacts || []).length;
                    const summary = ok
                        ? '✓ Configuration applied: ' + Object.entries(result.counts || {}).map(function (kv) { return kv[1] + ' ' + kv[0]; }).join(', ')
                          + ((result.unknownFacts || []).length ? ' — ⚠ unknown facts: ' + result.unknownFacts.join(', ') : '')
                        : '✗ Apply failed: ' + result.errors.join('; ');
                    pushT({ role: 'tool', text: summary, ok: clean });
                    aiLog('tool', '⚙ ' + summary, { input: tc.input, result: result });
                });
                history.push({ role: 'tool', results: results });
                flow.set('chatHistory', history);
                continue;
            }
            history.push({ role: 'assistant', text: parsed.text || '(empty response)', reasoning: parsed.reasoning });
            flow.set('chatHistory', history);
            const u = parsed.usage || {};
            aiLog('response', '← 200 ' + provider + ' stop=end tokens=' + u.in + '/' + u.out + (u.cacheRead ? ' (cached in=' + u.cacheRead + ')' : ''), { stop: 'end', text: parsed.text, body: body });
            pushT({ role: 'assistant', text: parsed.text || '(empty response)' });
            finalReached = true; break;
        }
        if (!finalReached) pushT({ role: 'error', text: '(stopped after 10 tool rounds — ask me to continue)' });
    } catch (e) {
        aiLog('error', '✗ TURN ERROR: ' + e, { error: String(e) });
        pushT({ role: 'error', text: 'Request failed: ' + e });
    } finally {
        flow.set('chatPending', false);
        flow.set('chatRetry', null);
    }
})();

const required = env.get('BMS_API_TOKEN');
if (required && (!msg.req || msg.req.headers['x-bms-token'] !== required)) { msg.statusCode = 401; msg.payload = { error: 'unauthorized' }; return msg; }
// Server-side display transcript + pending flag, polled by the chat widget (restores the
// conversation after navigation and surfaces a long turn's result without a held connection).
const rt = flow.get('chatRetry');
msg.statusCode = 200;
msg.payload = {
    messages: flow.get('chatTranscript') || [],
    pending: !!flow.get('chatPending'),
    retry: rt ? { seconds: Math.max(0, Math.ceil((rt.until - Date.now()) / 1000)), status: rt.status, provider: rt.provider, attempt: rt.attempt, max: rt.max, source: rt.source } : null
};
return msg;
